package org.jsoup.parser;

import org.junit.Test;
import static org.junit.Assert.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class TokenQueue_ESTest_test34 extends TokenQueue_ESTest_scaffolding {

    /**
     * matchesAny should report false when none of the candidate characters
     * match the character at the head of the queue. Here the queue starts with
     * a single quote ('), while the candidate set is four NUL ('�')
     * characters, so there is no match.
     */
    @Test(timeout = 4000)
    public void matchesAnyReturnsFalseWhenNoCandidateMatchesHead() throws Throwable {
        TokenQueue tokenQueue = new TokenQueue("'");

        char[] candidateChars = new char[4]; // four '�' (NUL) characters
        boolean matched = tokenQueue.matchesAny(candidateChars);

        assertFalse(matched);
    }
}
